#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (for syr2k)
#include "syr2k.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays A, B, C and scalars alpha, beta.
 *
 * Original C code:
 *
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < m; j++) {
 *       A[i][j] = ((i*j+1)%n) / n;
 *       B[i][j] = ((i*j+2)%m) / m;
 *     }
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       C[i][j] = ((i*j+3)%n) / m;
 *
 * C arrays are row-major: A[i][j].
 * Halide Buffers are column-major in the first dimension: A_buf(j, i).
 *
 * So we use:
 *   A_buf(k, i) = A[i][k]
 *   B_buf(k, i) = B[i][k]
 *   C_buf(j, i) = C[i][j]
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);
    *beta  = static_cast<num_t>(1.2);

    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // A is N x M in C, stored as A[i][j].
    // Buffer A has shape (m, n) and is indexed A(k, i) == A[i][k].
    init_A(k, i) = cast<num_t>((i * k + 1) % n) / cast<int>(n);

    // B is N x M in C, stored as B[i][j].
    // Buffer B has shape (m, n) and is indexed B(k, i) == B[i][k].
    init_B(k, i) = cast<num_t>((i * k + 2) % m) / cast<int>(m);

    // C is N x N in C, stored as C[i][j].
    // Buffer C has shape (n, n) and is indexed C(j, i) == C[i][j].
    init_C(j, i) = cast<num_t>((i * j + 3) % n) / cast<int>(m);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench / benchmark headers).
    int n = N;
    int m = M;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: N x N   -> Buffer(n_cols = n, n_rows = n)
    //   A: N x M   -> Buffer(m_cols = m, n_rows = n)
    //   B: N x M   -> Buffer(m_cols = m, n_rows = n)
    //
    // We always follow: first dimension = column index, second = row index.
    Buffer<num_t, 2> C(n, n);  // C(j, i) == C[i][j]
    Buffer<num_t, 2> A(m, n);  // A(k, i) == A[i][k]
    Buffer<num_t, 2> B(m, n);  // B(k, i) == B[i][k]

    // ImageParams to pass buffers into the Halide pipeline.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data.
    init_array(n, m, &alpha, &beta, C, A, B);

    // Bind Buffers to ImageParams.
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Halide algorithm for SYR2K.
    //
    // Original kernel_syr2k:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // We implement:
    //   C_out[i][j] = beta * C_in[i][j]  for j <= i
    //   C_out[i][j] = C_in[i][j]        for j >  i
    //   C_out[i][j] += sum_k alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]) for j <= i
    //
    // In Halide coordinates:
    //   i = row index (0..n-1)
    //   j = col index (0..n-1)
    //   k = inner dimension (0..m-1)
    //
    // Buffers:
    //   C_param(j, i) == C[i][j]
    //   A_param(k, j) == A[j][k]
    //   B_param(k, i) == B[i][k]
    //
    Var i("i"), j("j");
    RDom k(0, A.dim(0).extent(), "k");  // 0..m-1

    Func syr2k("syr2k");

    // Base (no reduction) definition: apply beta on the lower triangle, leave upper unchanged.
    syr2k(j, i) = select(j <= i,
                         Expr(beta) * C_param(j, i),
                         C_param(j, i));

    // Reduction over k: accumulate alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]) on the lower triangle.
    syr2k(j, i) += select(
        j <= i,
        Expr(alpha) * (A_param(k, j) * B_param(k, i) +
                       B_param(k, j) * A_param(k, i)),
        0);

    // Simple schedule mirroring the original loop structure:
    // pure definition:   for i (outer), j (inner)
    // update definition: for i (outer), k, j (inner)
    syr2k.reorder(j, i);
    syr2k.update().reorder(j, k, i);

    // JIT-compile the kernel.
    syr2k.compile_jit();

    // Time the execution.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C (in-place update is safe, as each output
    // element depends only on the corresponding input C(i,j) and A,B).
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output matrix (row-major order) if there is any argument.
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(jj, ii) == C[ii][jj]
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
