    //   if j <= i:
    //     C_out(i,j) = beta * C_in(i,j) +
    //                  alpha * sum_k ( A(j,k)*B(i,k) + B(j,k)*A(i,k) )
    //   else:
    //     C_out(i,j) = C_in(i,j)
    //
    // Mapping indices to Halide:
    //   C[i][j] -> C_param(j, i)
    //   A[j][k] -> A_param(k, j)
    //   B[i][k] -> B_param(k, i)
    //   B[j][k] -> B_param(k, j)
    //   A[i][k] -> A_param(k, i)
