    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // We model C_out(i,j) for all i,j, but restrict updates to j <= i
    // and leave C[i][j] unchanged for j > i (matching the original code).

    Var i("i"), j("j");
    RDom k(0, A.dim(0).extent(), "k");  // k ranges over [0, m)

    Func syr2k("syr2k");

    // Base: triangular scaling C[i][j] *= beta for j <= i, otherwise unchanged.
    // Mapping: C[i][j] -> C_param(j, i).
    syr2k(j, i) = select(j <= i,
                         Expr(beta) * C_param(j, i),
                         C_param(j, i));

    // Update: for each k, add alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]) for j <= i.
    // Mapping:
    //   A[j][k] -> A_param(k, j)
    //   B[i][k] -> B_param(k, i)
    //   B[j][k] -> B_param(k, j)
    //   A[i][k] -> A_param(k, i)
    Expr update_val =
        select(j <= i,
               Expr(alpha) *
                   (A_param(k, j) * B_param(k, i) +
                    B_param(k, j) * A_param(k, i)),
               cast<num_t>(0));

    syr2k(j, i) += update_val;

    // Schedule
    //
    // By default for syr2k(j, i) Halide emits:
    //   for i:
    //     for j:
    //       ...
    //
    // For the reduction, we want:
    //   for i:
    //     for k:
    //       for j:
    //         ...
    //
    // so we reorder the update step accordingly.
    syr2k.update().reorder(j, k, i);

    // Just-in-time compile the kernel
    syr2k.compile_jit();

    // Time the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: writes into C (same backing store as C_param)
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (for verification / DCE prevention)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, M, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "syr2k.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C and scalars alpha, beta.
 * C, A, B are Halide::Buffer with shapes:
 *   C: (n_cols, n_rows) = (n, n)
 *   A: (m_cols, n_rows) = (m, n)  // original A[n][m] -> A(col=j, row=i)
 *   B: (m_cols, n_rows) = (m, n)  // original B[n][m] -> B(col=j, row=i)
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // Original C code:
    // for i in [0,n)
    //   for j in [0,m)
    //     A[i][j] = ((i*j+1)%n)/n;
    //
    // A is declared as A[n][m], accessed as A[i][j].
    // Buffer A has shape (m, n) and is indexed A(j, i).
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // Original:
    // B[i][j] = ((i*j+2)%m)/m;
    init_B(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    // Original:
    // for i in [0,n)
    //   for j in [0,n)
    //     C[i][j] = ((i*j+3)%n)/m;
    //
    // C is C[n][n], Buffer C is C(j, i).
    init_C(j, i) = cast<num_t>((i * j + 3) % n) / cast<int>(m);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size from PolyBench-style macros.
    int n = N;
    int m = M;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers. Note: first dimension is the column (j), second is the row (i).
    // Original C:
    //   C[n][n], A[n][m], B[n][m], accessed as C[i][j], A[i][j], B[i][j].
    // We map to:
    //   C(j, i), A(j, i), B(j, i).
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);
    Halide::Buffer<num_t, 2> B(m, n);

    // ImageParams to pass the buffers into the Halide pipeline.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data.
    init_array(n, m, &alpha, &beta, C, A, B);

    // Bind ImageParams to the initialized buffers.
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Halide variables and reduction domain.
    Var i("i"), j("j");
    RDom k(0, m, "k"); // loops over the m dimension (columns of A/B)

    // syr2k computation:
    //
    // Original kernel_syr2k:
    //
    // for (i = 0; i < N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // Mathematically:
    //   For i >= j:
    //     C[i][j] = beta * C[i][j] +
    //               sum_{k=0..M-1} (alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]))
    //   For i < j:
    //     C[i][j] unchanged.
    //
    // Mapping indices to Buffers:
    //   C[i][j] -> C_param(j, i)
    //   A[j][k] -> A_param(k, j)
    //   B[i][k] -> B_param(k, i)
    //   B[j][k] -> B_param(k, j)
    //   A[i][k] -> A_param(k, i)

    Func syr2k("syr2k");

    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Base definition: scaled C on the lower triangle (i >= j), original C elsewhere.
    syr2k(j, i) = select(i >= j,
                         beta_e * C_param(j, i),
                         C_param(j, i));

    // Reduction over k: accumulate the rank-2 update on the lower triangle only.
    syr2k(j, i) += select(
        i >= j,
        alpha_e * (A_param(k, j) * B_param(k, i) +
                   B_param(k, j) * A_param(k, i)),
        0);

    // Basic schedule: keep j (column) as the innermost dimension.
    syr2k.reorder(j, i);
    syr2k.update().reorder(j, k, i);

    // Compile the kernel to machine code.
    syr2k.compile_jit();

    // Time the execution.
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into C (in-place update of C).
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (optional), similar to gemm.cpp example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
